import { buildMcqs, type RawMcq } from './build'
import type { AssessSet } from './types'

// Aptitude sets used in company screening rounds. Every numeric answer was checked by calculation.

const quant: RawMcq[] = [
  { id: 'markup-discount', topic: 'Profit and loss', difficulty: 'medium', q: 'A shopkeeper buys an item for ₹800, marks it up by 25% and then allows a 10% discount on the marked price. What is the profit percentage?', right: '12.5%', wrong: ['15%', '10%', '11.25%'], explain: 'Marked price = 800 × 1.25 = 1000. Selling price = 1000 × 0.9 = 900. Profit = 100 on a cost of 800, which is 12.5%. Simply subtracting 10 from 25 (15%) ignores that the discount applies to the larger marked price.', seconds: 75, tags: ['profit-loss', 'percentage'] },
  { id: 'train-platform', topic: 'Time, speed and distance', difficulty: 'medium', q: 'A 150 m long train passes a pole in 10 seconds. How long does it take to cross a platform 250 m long at the same speed?', right: '26⅔ seconds', wrong: ['25 seconds', '40 seconds', '16⅔ seconds'], explain: 'Speed = 150 / 10 = 15 m/s. Crossing the platform means covering train plus platform: 400 m. Time = 400 / 15 = 26⅔ s. Ignoring the train length gives 16⅔ s.', seconds: 80, tags: ['trains', 'speed'] },
  { id: 'work-together', topic: 'Time and work', difficulty: 'easy', q: 'A can finish a job in 12 days and B in 18 days. Working together, in how many days do they finish it?', right: '7.2 days', wrong: ['15 days', '6 days', '7.5 days'], explain: 'Together they do 1/12 + 1/18 = 5/36 of the job a day, so the job takes 36/5 = 7.2 days. Averaging the two times (15) is the common slip.', seconds: 60, tags: ['work', 'rates'] },
  { id: 'compound-interest', topic: 'Interest', difficulty: 'easy', q: 'What is the compound interest on ₹10,000 at 10% per annum, compounded annually, for 2 years?', right: '₹2,100', wrong: ['₹2,000', '₹2,200', '₹2,310'], explain: 'Amount = 10,000 × 1.1² = 12,100, so interest is ₹2,100. Simple interest would give ₹2,000, and ₹2,310 is the interest for 3 years.', seconds: 50, tags: ['interest'] },
  { id: 'ratio-sum', topic: 'Ratio and proportion', difficulty: 'easy', q: 'Two numbers are in the ratio 3 : 5 and their sum is 96. What is the larger number?', right: '60', wrong: ['36', '48', '56'], explain: 'The 8 parts make 96, so one part is 12 and the larger number is 5 × 12 = 60. 36 is the smaller number.', seconds: 40, tags: ['ratio'] },
  { id: 'average-remove', topic: 'Averages', difficulty: 'medium', q: 'The average of 5 numbers is 24. When one number is removed, the average of the remaining four becomes 22. What number was removed?', right: '32', wrong: ['30', '34', '36'], explain: 'The total was 5 × 24 = 120 and the remaining total is 4 × 22 = 88, so the removed number is 120 − 88 = 32.', seconds: 55, tags: ['averages'] },
  { id: 'mixture-water', topic: 'Mixtures', difficulty: 'medium', q: 'A 40 litre mixture of milk and water is in the ratio 3 : 1. How many litres of water must be added to make the ratio 1 : 1?', right: '20 litres', wrong: ['10 litres', '30 litres', '15 litres'], explain: 'The mixture has 30 L of milk and 10 L of water. For a 1 : 1 ratio the water must also be 30 L, so add 20 L.', seconds: 60, tags: ['mixture', 'ratio'] },
  { id: 'dice-sum', topic: 'Probability', difficulty: 'easy', q: 'Two fair dice are thrown. What is the probability that the sum is 8?', right: '5/36', wrong: ['1/6', '1/9', '7/36'], explain: 'The sums of 8 are (2,6), (3,5), (4,4), (5,3) and (6,2): 5 outcomes out of 36. 1/6 would need 6 outcomes (that is the probability of a sum of 7).', seconds: 50, tags: ['probability', 'dice'] },
  { id: 'permute-level', topic: 'Permutations', difficulty: 'medium', q: 'In how many different ways can the letters of the word LEVEL be arranged?', right: '30', wrong: ['120', '60', '24'], explain: 'Five letters with L repeated twice and E repeated twice: 5! / (2! × 2!) = 120 / 4 = 30. 120 forgets the repeats, and 60 divides by only one repeated pair.', seconds: 60, tags: ['permutations'] },
  { id: 'committee', topic: 'Combinations', difficulty: 'medium', q: 'A committee of 3 is chosen from 6 men and 4 women. In how many ways can it include at least one woman?', right: '100', wrong: ['120', '80', '96'], explain: 'All committees: C(10,3) = 120. Those with no woman: C(6,3) = 20. So 120 − 20 = 100.', seconds: 70, tags: ['combinations'] },
  { id: 'average-speed', topic: 'Time, speed and distance', difficulty: 'medium', q: 'A car drives to a town at 60 km/h and returns along the same road at 40 km/h. What is its average speed for the round trip?', right: '48 km/h', wrong: ['50 km/h', '45 km/h', '52 km/h'], explain: 'For equal distances use the harmonic mean: 2 × 60 × 40 / (60 + 40) = 48 km/h. The simple average, 50, is wrong because more time is spent at the slower speed.', seconds: 50, tags: ['speed', 'average'] },
  { id: 'up-down', topic: 'Percentage', difficulty: 'easy', q: 'The price of an item rises by 20% and then falls by 20%. What is the net change?', right: 'A decrease of 4%', wrong: ['No change', 'An increase of 4%', 'A decrease of 2%'], explain: '1.2 × 0.8 = 0.96, so the final price is 96% of the original, a 4% decrease. The second change applies to the already larger price.', seconds: 40, tags: ['percentage'] },
  { id: 'simple-interest-double', topic: 'Interest', difficulty: 'medium', q: 'A sum of money doubles itself in 8 years at simple interest. What is the rate per annum?', right: '12.5%', wrong: ['10%', '8%', '15%'], explain: 'Interest equals the principal after 8 years, so P = P × R × 8 / 100, which gives R = 12.5%.', seconds: 50, tags: ['interest'] },
  { id: 'boat-stream', topic: 'Boats and streams', difficulty: 'hard', q: 'A boat travels at 12 km/h in still water and the stream flows at 3 km/h. How long does a trip of 36 km downstream and 36 km back upstream take?', right: '6.4 hours', wrong: ['6 hours', '5.8 hours', '7.2 hours'], explain: 'Downstream speed is 15 km/h (2.4 h) and upstream speed is 9 km/h (4 h): total 6.4 h. Using the still-water speed for both legs gives 6 h.', seconds: 80, tags: ['boats', 'speed'] },
  { id: 'hcf-lcm', topic: 'Numbers', difficulty: 'medium', q: 'The HCF of two numbers is 12 and their LCM is 180. If one number is 36, what is the other?', right: '60', wrong: ['15', '72', '48'], explain: 'The product of two numbers equals HCF × LCM: 12 × 180 = 2160. Dividing by 36 gives 60.', seconds: 45, tags: ['hcf-lcm'] },
  { id: 'ages', topic: 'Ages', difficulty: 'medium', q: 'A father is four times as old as his son. After 6 years he will be three times as old as the son. What is the father\'s present age?', right: '48 years', wrong: ['40 years', '36 years', '52 years'], explain: 'Let the son be x. Then 4x + 6 = 3(x + 6), so x = 12 and the father is 48. Check: in 6 years they are 54 and 18.', seconds: 70, tags: ['ages', 'equations'] },
  { id: 'articles-profit', topic: 'Profit and loss', difficulty: 'hard', q: 'The selling price of 15 articles equals the cost price of 20 articles. What is the profit percentage?', right: '33⅓%', wrong: ['25%', '20%', '30%'], explain: 'From 15 × SP = 20 × CP we get SP = (4/3) CP, a profit of one third of the cost, which is 33⅓%. 25% is the profit on the selling price, not on the cost.', seconds: 75, tags: ['profit-loss'] },
  { id: 'pipes', topic: 'Time and work', difficulty: 'medium', q: 'A pipe fills a tank in 6 hours and another pipe empties it in 10 hours. With both open, how long does the empty tank take to fill?', right: '15 hours', wrong: ['16 hours', '4 hours', '12 hours'], explain: 'Net rate = 1/6 − 1/10 = 1/15 of the tank per hour, so the tank fills in 15 hours.', seconds: 55, tags: ['pipes', 'rates'] },
  { id: 'rectangle-area', topic: 'Percentage', difficulty: 'easy', q: 'The length of a rectangle increases by 20% and its breadth decreases by 10%. What happens to the area?', right: 'It increases by 8%', wrong: ['It increases by 10%', 'It decreases by 8%', 'It does not change'], explain: 'New area = 1.2 × 0.9 = 1.08 times the old area, an 8% increase. Adding +20% and −10% (giving 10%) forgets that the changes multiply.', seconds: 40, tags: ['percentage', 'area'] },
  { id: 'even-sum', topic: 'Number series', difficulty: 'easy', q: 'What is the sum of all even numbers from 2 to 50?', right: '650', wrong: ['625', '675', '600'], explain: 'There are 25 even numbers: 2 + 4 + ... + 50 = 2 × (1 + 2 + ... + 25) = 2 × 325 = 650. 625 is the sum of the first 25 odd numbers.', seconds: 45, tags: ['series', 'sum'] },
  { id: 'successive-discount', topic: 'Percentage', difficulty: 'easy', q: 'A shop gives successive discounts of 20% and 10% on an item. What single discount is the same?', right: '28%', wrong: ['30%', '27%', '25%'], explain: 'The price becomes 0.8 × 0.9 = 0.72 of the original, which is a 28% discount. Adding 20% and 10% gives 30%, but the second discount applies to the reduced price.', seconds: 40, tags: ['percentage', 'discount'] },
  { id: 'trains-opposite', topic: 'Time, speed and distance', difficulty: 'hard', q: 'Two trains 100 m and 120 m long run in opposite directions at 54 km/h and 36 km/h. How long do they take to cross each other?', right: '8.8 seconds', wrong: ['10 seconds', '8 seconds', '12.2 seconds'], explain: 'Relative speed = 90 km/h = 25 m/s. They must cover 100 + 120 = 220 m, so the time is 220 / 25 = 8.8 s.', seconds: 80, tags: ['trains', 'relative-speed'] },
  { id: 'partnership', topic: 'Partnership', difficulty: 'medium', q: 'A invests ₹6,000 for 12 months and B invests ₹8,000 for 6 months. Of a total profit of ₹14,000, how much does A receive?', right: '₹8,400', wrong: ['₹7,000', '₹6,000', '₹9,600'], explain: 'Profit is shared in the ratio of money × time: 6000 × 12 : 8000 × 6 = 72000 : 48000 = 3 : 2. A gets 3/5 of 14,000 = ₹8,400.', seconds: 65, tags: ['partnership', 'ratio'] },
  { id: 'ci-si-gap', topic: 'Interest', difficulty: 'medium', q: 'What is the difference between compound and simple interest on ₹5,000 at 10% per annum for 2 years?', right: '₹50', wrong: ['₹100', '₹25', '₹500'], explain: 'Simple interest = ₹1,000. Compound interest = 5000 × 1.21 − 5000 = ₹1,050. The difference is ₹50, which equals P × (r/100)² for two years.', seconds: 55, tags: ['interest'] },
  { id: 'circle-area', topic: 'Geometry', difficulty: 'easy', q: 'What is the area of a circle of radius 7 cm? (Use π = 22/7.)', right: '154 cm²', wrong: ['44 cm²', '308 cm²', '49 cm²'], explain: 'Area = π r² = (22/7) × 7 × 7 = 154 cm². 44 is the circumference, and 308 is twice the area.', seconds: 30, tags: ['geometry', 'area'] },
  { id: 'two-aces', topic: 'Probability', difficulty: 'hard', q: 'Two cards are drawn one after another, without replacement, from a standard 52-card deck. What is the probability that both are aces?', right: '1/221', wrong: ['1/169', '1/52', '4/663'], explain: 'P = (4/52) × (3/51) = 12/2652 = 1/221. Using 4/52 twice (with replacement) would give 1/169.', seconds: 60, tags: ['probability', 'cards'] },
  { id: 'men-leave', topic: 'Time and work', difficulty: 'hard', q: '12 men can finish a job in 10 days. After 4 days, 6 men leave. How many more days do the remaining men need?', right: '12 days', wrong: ['10 days', '6 days', '15 days'], explain: 'The job is 120 man-days. 4 days of 12 men do 48, leaving 72 man-days. With 6 men that takes 72 / 6 = 12 more days.', seconds: 75, tags: ['work', 'man-days'] },
  { id: 'replace-average', topic: 'Averages', difficulty: 'medium', q: 'The average age of 6 men rises by 2 years when a 40-year-old man is replaced by a new man. How old is the new man?', right: '52 years', wrong: ['46 years', '48 years', '54 years'], explain: 'The total age rises by 6 × 2 = 12 years, so the new man is 40 + 12 = 52.', seconds: 45, tags: ['averages'] },
  { id: 'remainder-power', topic: 'Number system', difficulty: 'medium', q: 'What is the remainder when 2¹⁰ is divided by 7?', right: '2', wrong: ['1', '3', '4'], explain: '2³ = 8 leaves remainder 1 when divided by 7, so 2¹⁰ = (2³)³ × 2 leaves 1 × 2 = 2. Check: 1024 = 7 × 146 + 2.', seconds: 60, tags: ['remainders', 'number-system'] },
  { id: 'unit-digit', topic: 'Number system', difficulty: 'medium', q: 'What is the unit digit of 7⁴⁵?', right: '7', wrong: ['1', '3', '9'], explain: 'The unit digits of the powers of 7 repeat every four steps: 7, 9, 3, 1. Since 45 = 4 × 11 + 1, 7⁴⁵ has the same unit digit as 7¹, which is 7.', seconds: 55, tags: ['unit-digit', 'cycles'] },
  { id: 'percent-less', topic: 'Percentage', difficulty: 'easy', q: 'A is 25% more than B. By what percentage is B less than A?', right: '20%', wrong: ['25%', '30%', '15%'], explain: 'Let B = 100, so A = 125. B is 25 less than A, and 25 / 125 = 20%. The base changes, so the two percentages differ.', seconds: 45, tags: ['percentage'] },
  { id: 'alligation', topic: 'Mixtures', difficulty: 'medium', q: 'Rice costing ₹40 per kg is mixed with rice costing ₹60 per kg to get a mixture worth ₹52 per kg. In what ratio are they mixed (cheaper : dearer)?', right: '2 : 3', wrong: ['3 : 2', '1 : 1', '4 : 5'], explain: 'By alligation, the cheaper and dearer quantities are in the ratio (60 − 52) : (52 − 40) = 8 : 12 = 2 : 3. The mixture is closer to the dearer price, so more of the dearer rice is used.', seconds: 70, tags: ['alligation', 'mixture'] },
  { id: 'population', topic: 'Percentage', difficulty: 'easy', q: 'A town has 20,000 people and the population grows by 10% every year. What is the population after 2 years?', right: '24,200', wrong: ['24,000', '24,400', '22,000'], explain: 'Growth compounds: 20,000 × 1.1 × 1.1 = 24,200. Adding 10% twice to the original (24,000) ignores that the second increase applies to the larger number.', seconds: 40, tags: ['growth', 'percentage'] },
  { id: 'cube-surface', topic: 'Mensuration', difficulty: 'medium', q: 'The volume of a cube is 125 cm³. What is its total surface area?', right: '150 cm²', wrong: ['125 cm²', '100 cm²', '75 cm²'], explain: 'The side is the cube root of 125, which is 5 cm. The surface area is 6 × 5² = 150 cm².', seconds: 45, tags: ['cube', 'mensuration'] },
  { id: 'twice-as-fast', topic: 'Time and work', difficulty: 'medium', q: 'A is twice as fast as B. Together they finish a job in 12 days. In how many days can A alone finish it?', right: '18 days', wrong: ['24 days', '36 days', '16 days'], explain: 'If B does x of the job a day, A does 2x, so 3x = 1/12 and x = 1/36. A alone does 1/18 a day and takes 18 days.', seconds: 60, tags: ['work', 'rates'] },
  { id: 'late-early', topic: 'Time, speed and distance', difficulty: 'hard', q: 'A student walking at 5 km/h reaches school 6 minutes late. Walking at 6 km/h, he reaches 5 minutes early. How far is the school?', right: '5.5 km', wrong: ['6 km', '4.5 km', '5 km'], explain: 'The time difference is 11 minutes = 11/60 hour. So d/5 − d/6 = 11/60, which gives d/30 = 11/60 and d = 5.5 km.', seconds: 85, tags: ['speed', 'distance'] },
  { id: 'profit-percent', topic: 'Profit and loss', difficulty: 'easy', q: 'An article bought for ₹500 is sold for ₹560. What is the profit percentage?', right: '12%', wrong: ['10%', '11.2%', '15%'], explain: 'Profit = 60 on a cost of 500, which is 60/500 = 12%. Profit percentage uses the cost price as the base.', seconds: 30, tags: ['profit-loss'] },
  { id: 'markup-percent', topic: 'Profit and loss', difficulty: 'hard', q: 'A trader makes a 20% profit after allowing a 10% discount on the marked price. By what percentage is the marked price above the cost price?', right: '33⅓%', wrong: ['30%', '32%', '25%'], explain: 'Let the cost be 100. The selling price is 120, which is 90% of the marked price, so the marked price is 120 / 0.9 = 133⅓, which is 33⅓% above the cost.', seconds: 80, tags: ['profit-loss', 'discount'] },
  { id: 'si-amount', topic: 'Interest', difficulty: 'easy', q: 'What amount will ₹4,000 become after 3 years at 5% simple interest per annum?', right: '₹4,600', wrong: ['₹4,630', '₹4,500', '₹4,150'], explain: 'Simple interest = 4000 × 5 × 3 / 100 = ₹600, so the amount is ₹4,600. ₹4,630 would be the amount with compound interest.', seconds: 35, tags: ['interest'] },
  { id: 'divisible-nine', topic: 'Number system', difficulty: 'medium', q: 'What is the smallest number to be added to 1234 so that the result is divisible by 9?', right: '8', wrong: ['1', '7', '9'], explain: 'A number is divisible by 9 when its digit sum is. The digit sum of 1234 is 10, which leaves remainder 1 on division by 9, so we must add 9 − 1 = 8 (giving 1242).', seconds: 45, tags: ['divisibility'] },
  { id: 'women-together', topic: 'Permutations', difficulty: 'hard', q: '5 men and 3 women sit in a row. In how many ways can they sit if the 3 women must sit together?', right: '4,320', wrong: ['720', '40,320', '2,160'], explain: 'Treat the three women as one block: 6 units can be arranged in 6! = 720 ways, and the women can be ordered inside the block in 3! = 6 ways. 720 × 6 = 4,320.', seconds: 75, tags: ['permutations'] },
  { id: 'two-blue', topic: 'Probability', difficulty: 'medium', q: 'A bag has 4 red and 6 blue balls. Two balls are drawn one after another without replacement. What is the probability that both are blue?', right: '1/3', wrong: ['9/25', '3/10', '2/5'], explain: 'P = (6/10) × (5/9) = 30/90 = 1/3. With replacement it would be (6/10)² = 9/25.', seconds: 55, tags: ['probability'] },
  { id: 'missing-number', topic: 'Averages', difficulty: 'hard', q: 'The average of 25 numbers is 40. The average of the first 13 is 38 and of the last 13 is 44. What is the 13th number?', right: '66', wrong: ['60', '62', '70'], explain: 'The 13th number is counted in both groups. Total of the groups = 13 × 38 + 13 × 44 = 1066, while the true total is 25 × 40 = 1000, so the 13th number is 1066 − 1000 = 66.', seconds: 80, tags: ['averages'] },
  { id: 'bells', topic: 'Numbers', difficulty: 'medium', q: 'Three bells ring every 12, 15 and 20 minutes. They ring together at 8:00 a.m. After how many minutes will they next ring together?', right: '60 minutes', wrong: ['45 minutes', '120 minutes', '30 minutes'], explain: 'The next common time is the LCM of 12, 15 and 20, which is 60 minutes.', seconds: 45, tags: ['lcm'] },
  { id: 'rectangle-perimeter', topic: 'Mensuration', difficulty: 'medium', q: 'The perimeter of a rectangle is 56 cm and its length and breadth are in the ratio 5 : 2. What is its area?', right: '160 cm²', wrong: ['140 cm²', '196 cm²', '180 cm²'], explain: 'Length + breadth = 28 cm, split 5 : 2 gives 20 cm and 8 cm. The area is 20 × 8 = 160 cm².', seconds: 55, tags: ['rectangle', 'ratio'] },
  { id: 'thirty-percent', topic: 'Percentage', difficulty: 'easy', q: '30% of a number is 90. What is 40% of the same number?', right: '120', wrong: ['108', '126', '135'], explain: 'The number is 90 / 0.3 = 300, and 40% of 300 is 120.', seconds: 30, tags: ['percentage'] },
  { id: 'ratio-chain', topic: 'Ratio and proportion', difficulty: 'medium', q: 'If A : B = 2 : 3 and B : C = 4 : 5, what is A : C?', right: '8 : 15', wrong: ['2 : 5', '6 : 15', '10 : 12'], explain: 'Make B the same in both: A : B = 8 : 12 and B : C = 12 : 15. So A : B : C = 8 : 12 : 15 and A : C = 8 : 15.', seconds: 50, tags: ['ratio'] },
  { id: 'still-water', topic: 'Boats and streams', difficulty: 'medium', q: 'A boat goes 20 km downstream in 2 hours and 12 km upstream in 2 hours. What is its speed in still water?', right: '8 km/h', wrong: ['10 km/h', '6 km/h', '9 km/h'], explain: 'Downstream speed = 10 km/h and upstream speed = 6 km/h. Still-water speed is their average: (10 + 6) / 2 = 8 km/h (the stream is 2 km/h).', seconds: 55, tags: ['boats'] },
  { id: 'si-rate', topic: 'Interest', difficulty: 'medium', q: 'A sum of ₹2,400 earns ₹288 as simple interest in 2 years. What is the rate of interest per annum?', right: '6%', wrong: ['5%', '7.2%', '12%'], explain: 'Rate = interest × 100 / (principal × time) = 288 × 100 / (2400 × 2) = 6%.', seconds: 45, tags: ['interest'] },
  { id: 'sum-difference', topic: 'Algebra', difficulty: 'easy', q: 'The sum of two numbers is 45 and their difference is 9. What is the larger number?', right: '27', wrong: ['36', '24', '18'], explain: 'The larger number is (sum + difference) / 2 = (45 + 9) / 2 = 27, and the smaller is 18.', seconds: 30, tags: ['equations'] },
]

const logical: RawMcq[] = [
  { id: 'series-pronic', topic: 'Number series', difficulty: 'easy', q: 'Find the next number: 2, 6, 12, 20, 30, ?', right: '42', wrong: ['40', '44', '38'], explain: 'The differences are 4, 6, 8, 10, so the next is 12 and 30 + 12 = 42. Equivalently the terms are n(n + 1).', seconds: 40, tags: ['series'] },
  { id: 'series-double-plus', topic: 'Number series', difficulty: 'medium', q: 'Find the next number: 3, 7, 15, 31, 63, ?', right: '127', wrong: ['125', '126', '129'], explain: 'Each term is double the previous one plus 1: 63 × 2 + 1 = 127.', seconds: 45, tags: ['series'] },
  { id: 'series-letters', topic: 'Letter series', difficulty: 'medium', q: 'Find the next letter: A, C, F, J, O, ?', right: 'U', wrong: ['T', 'V', 'S'], explain: 'The gaps between letters are +2, +3, +4, +5, so the next gap is +6: O (15) + 6 = 21, which is U.', seconds: 50, tags: ['series', 'letters'] },
  { id: 'code-reverse', topic: 'Coding and decoding', difficulty: 'medium', q: 'In a code language A = Z, B = Y, C = X and so on (the alphabet reversed). How is DOG written?', right: 'WLT', wrong: ['WLS', 'VLT', 'WKT'], explain: 'Each letter is replaced by its mirror: D → W, O → L, G → T.', seconds: 50, tags: ['coding-decoding'] },
  { id: 'code-shift', topic: 'Coding and decoding', difficulty: 'easy', q: 'If each letter is moved two places forward, BAKE is written as DCMG. How is MILK written in the same code?', right: 'OKNM', wrong: ['OKMN', 'NJMB', 'OLNM'], explain: 'Move each letter two places on: M → O, I → K, L → N, K → M.', seconds: 40, tags: ['coding-decoding'] },
  { id: 'blood-relation', topic: 'Blood relations', difficulty: 'medium', q: 'Pointing to a girl in a photo, Ravi says, "She is the daughter of my grandfather\'s only son." How is the girl related to Ravi?', right: 'Sister', wrong: ['Cousin', 'Mother', 'Niece'], explain: 'The only son of Ravi\'s grandfather is Ravi\'s father (Ravi\'s father\'s father is the grandfather). The daughter of Ravi\'s father is Ravi\'s sister. "Cousin" would need an uncle or aunt.', seconds: 60, tags: ['blood-relations'] },
  { id: 'direction', topic: 'Directions', difficulty: 'easy', q: 'Asha walks 5 km north, turns right and walks 3 km, then turns right again and walks 5 km. How far and in which direction is she from the start?', right: '3 km east', wrong: ['3 km west', '5 km east', '13 km north'], explain: 'North 5 km, then east 3 km (a right turn from north), then south 5 km (a right turn from east). The north and south parts cancel, leaving 3 km east.', seconds: 50, tags: ['directions'] },
  { id: 'syllogism', topic: 'Syllogisms', difficulty: 'medium', q: 'Statements: All pens are books. Some books are cups.\nConclusions: I. Some pens are cups.  II. Some cups are books.\nWhich conclusion follows?', right: 'Only II follows', wrong: ['Only I follows', 'Both I and II follow', 'Neither follows'], explain: '"Some books are cups" can be reversed to "some cups are books", so II follows. Nothing connects the pens to the cups: the cups may be books that are not pens, so I does not follow.', seconds: 60, tags: ['syllogism'] },
  { id: 'seating', topic: 'Seating arrangement', difficulty: 'hard', q: 'Five friends A, B, C, D and E sit in a row facing north. C sits immediately to the right of A. B sits at the extreme right end. D sits immediately to the left of E. E does not sit at either end. A does not sit at the extreme left. Who sits in the middle?', right: 'A', wrong: ['C', 'D', 'E'], explain: 'B is last. The blocks "A C" and "D E" fill the first four places; E can not be at an end, and A can not be first, so the order is D, E, A, C, B. The middle (third) seat is A.', seconds: 100, tags: ['seating', 'puzzle'] },
  { id: 'odd-one-out', topic: 'Odd one out', difficulty: 'easy', q: 'Find the odd one out: 8, 27, 64, 100, 125.', right: '100', wrong: ['27', '64', '8'], explain: 'All the others are perfect cubes (2³, 3³, 4³, 5³); 100 is not.', seconds: 30, tags: ['odd-one-out'] },
  { id: 'ranking', topic: 'Ranking', difficulty: 'easy', q: 'In a class, Priya is 12th from the top and 25th from the bottom. How many students are in the class?', right: '36', wrong: ['37', '38', '35'], explain: 'Total = rank from top + rank from bottom − 1 = 12 + 25 − 1 = 36, since Priya is counted in both ranks.', seconds: 35, tags: ['ranking'] },
  { id: 'clock-angle', topic: 'Clocks', difficulty: 'medium', q: 'What is the angle between the hour and minute hands at 3:30?', right: '75°', wrong: ['90°', '60°', '105°'], explain: 'At 3:30 the minute hand is at 180° and the hour hand has moved to 3 × 30 + 15 = 105°. The difference is 75°. Forgetting that the hour hand moves gives 90°.', seconds: 55, tags: ['clocks'] },
  { id: 'calendar', topic: 'Calendars', difficulty: 'easy', q: 'Today is Wednesday. What day of the week will it be after 100 days?', right: 'Friday', wrong: ['Thursday', 'Saturday', 'Sunday'], explain: '100 = 14 × 7 + 2, so the weekday moves 2 days on: Wednesday → Friday.', seconds: 35, tags: ['calendars'] },
  { id: 'analogy', topic: 'Analogies', difficulty: 'easy', q: 'Book : Library :: Painting : ?', right: 'Gallery', wrong: ['Frame', 'Artist', 'Canvas'], explain: 'A library is the place where books are kept and displayed, as a gallery is for paintings. A frame and a canvas are parts of a painting, and the artist is its maker.', seconds: 30, tags: ['analogy'] },
  { id: 'truth-tellers', topic: 'Logical puzzles', difficulty: 'hard', q: 'Each of A, B and C either always tells the truth or always lies. A says "B is a liar". B says "C is a liar". C says "A and B are both liars". Who is telling the truth?', right: 'Only B', wrong: ['Only A', 'Only C', 'A and C'], explain: 'A speaker is truthful exactly when the statement is true. If C were truthful, A and B would both be liars; but a liar A saying "B is a liar" means B is truthful, a contradiction. So C lies. Then B, who says "C is a liar", tells the truth, and A, who says B lies, is a liar.', seconds: 100, tags: ['puzzle', 'truth-liar'] },
  { id: 'inequality', topic: 'Inequalities', difficulty: 'medium', q: 'Given P > Q ≥ R = S, which conclusion is definitely true?', right: 'P > S', wrong: ['Q > S', 'R > Q', 'S > P'], explain: 'Chain the statement: P is greater than Q, Q is at least R, and R equals S, so P > S. Q ≥ S only, so Q > S is not certain.', seconds: 40, tags: ['inequality'] },
  { id: 'series-fibonacci', topic: 'Number series', difficulty: 'easy', q: 'Find the next number: 2, 3, 5, 8, 13, ?', right: '21', wrong: ['20', '24', '26'], explain: 'Each term is the sum of the two before it: 8 + 13 = 21 (the Fibonacci pattern).', seconds: 30, tags: ['series'] },
  { id: 'series-factorial', topic: 'Number series', difficulty: 'medium', q: 'Find the next number: 1, 2, 6, 24, 120, ?', right: '720', wrong: ['600', '480', '840'], explain: 'The multipliers are 2, 3, 4, 5, so the next is × 6: 120 × 6 = 720 (these are factorials).', seconds: 35, tags: ['series'] },
  { id: 'series-double-one', topic: 'Number series', difficulty: 'medium', q: 'Find the next number: 5, 11, 23, 47, 95, ?', right: '191', wrong: ['190', '189', '195'], explain: 'Each term is twice the previous one plus 1: 95 × 2 + 1 = 191.', seconds: 40, tags: ['series'] },
  { id: 'letter-sum', topic: 'Coding and decoding', difficulty: 'medium', q: 'If each letter has its alphabet position as value, APPLE = 1 + 16 + 16 + 12 + 5 = 50. What is the value of BANANA?', right: '33', wrong: ['31', '35', '36'], explain: 'B = 2, A = 1, N = 14, A = 1, N = 14, A = 1, and 2 + 1 + 14 + 1 + 14 + 1 = 33.', seconds: 45, tags: ['coding-decoding'] },
  { id: 'blood-chain', topic: 'Blood relations', difficulty: 'hard', q: 'A is the sister of B. C is the mother of B. D is the father of C. E is the mother of D. How is A related to E?', right: 'Great-granddaughter', wrong: ['Granddaughter', 'Daughter', 'Niece'], explain: 'A and B are children of C. C is the child of D, and D is the child of E. So E is the grandmother of C and the great-grandmother of A.', seconds: 70, tags: ['blood-relations'] },
  { id: 'turns', topic: 'Directions', difficulty: 'medium', q: 'Ravi faces north. He turns 90° to the right and then 135° to the left. Which direction does he face now?', right: 'North-west', wrong: ['South-west', 'North-east', 'South-east'], explain: 'Right 90° from north points east. Turning 135° left from east passes north (90°) and ends 45° beyond it, which is north-west.', seconds: 50, tags: ['directions'] },
  { id: 'syllogism-chain', topic: 'Syllogisms', difficulty: 'medium', q: 'Statements: All doctors are teachers. All teachers are artists.\nConclusions: I. All doctors are artists.  II. Some artists are doctors.\nWhich conclusion follows?', right: 'Both I and II follow', wrong: ['Only I follows', 'Only II follows', 'Neither follows'], explain: 'Chaining two "all" statements gives "all doctors are artists" (I). Since every doctor is an artist, at least some artists are doctors (II).', seconds: 60, tags: ['syllogism'] },
  { id: 'rank-from-right', topic: 'Ranking', difficulty: 'easy', q: 'Meena is 15th from the left in a row of 40 students. What is her position from the right?', right: '26th', wrong: ['25th', '24th', '27th'], explain: 'Position from the right = total − position from the left + 1 = 40 − 15 + 1 = 26.', seconds: 30, tags: ['ranking'] },
  { id: 'series-square-plus', topic: 'Number series', difficulty: 'easy', q: 'Find the next number: 2, 5, 10, 17, 26, ?', right: '37', wrong: ['36', '35', '40'], explain: 'The terms are n² + 1: 1+1, 4+1, 9+1, 16+1, 25+1, so the next is 36 + 1 = 37. The differences 3, 5, 7, 9, 11 confirm it.', seconds: 40, tags: ['series'] },
  { id: 'series-doubling-gaps', topic: 'Number series', difficulty: 'hard', q: 'Find the next number: 100, 96, 88, 72, 40, ?', right: '-24', wrong: ['0', '-8', '-16'], explain: 'The differences are −4, −8, −16, −32, doubling each time, so the next is −64: 40 − 64 = −24.', seconds: 60, tags: ['series'] },
  { id: 'series-odd-gaps', topic: 'Number series', difficulty: 'medium', q: 'Find the next number: 3, 6, 11, 18, 27, ?', right: '38', wrong: ['36', '37', '39'], explain: 'The differences are the odd numbers 3, 5, 7, 9, so the next is 11: 27 + 11 = 38.', seconds: 40, tags: ['series'] },
  { id: 'series-letters-gap', topic: 'Letter series', difficulty: 'medium', q: 'Find the next letter: B, D, G, K, P, ?', right: 'V', wrong: ['U', 'W', 'T'], explain: 'The gaps are +2, +3, +4, +5, so the next gap is +6: P (16) + 6 = 22, which is V.', seconds: 45, tags: ['series', 'letters'] },
  { id: 'series-alternating', topic: 'Number series', difficulty: 'hard', q: 'Find the next number: 2, 3, 4, 6, 8, 12, 16, ?', right: '24', wrong: ['20', '22', '32'], explain: 'It is two interleaved series: 2, 4, 8, 16 and 3, 6, 12. Each doubles, so after 16 comes 12 × 2 = 24.', seconds: 60, tags: ['series'] },
  { id: 'code-plus-one', topic: 'Coding and decoding', difficulty: 'easy', q: 'If MONDAY is written as NPOEBZ, how is FRIDAY written?', right: 'GSJEBZ', wrong: ['GSJEAZ', 'ESHDZX', 'GSIEBZ'], explain: 'Every letter is moved one place forward: F → G, R → S, I → J, D → E, A → B, Y → Z.', seconds: 35, tags: ['coding-decoding'] },
  { id: 'symbol-swap', topic: 'Coding and decoding', difficulty: 'hard', q: 'If + means ×, − means ÷, × means + and ÷ means −, what is the value of 12 + 3 × 4 − 2?', right: '38', wrong: ['18', '14', '46'], explain: 'Replace the symbols with their meanings: 12 × 3 + 4 ÷ 2. By the usual order of operations that is 36 + 2 = 38.', seconds: 60, tags: ['symbols'] },
  { id: 'code-wrap', topic: 'Coding and decoding', difficulty: 'medium', q: 'In a code, every letter is replaced by the next letter (Z is followed by A). How is XYZ written?', right: 'YZA', wrong: ['ZAB', 'WXY', 'YZZ'], explain: 'X → Y, Y → Z and Z wraps around to A, so XYZ becomes YZA.', seconds: 30, tags: ['coding-decoding'] },
  { id: 'blood-wife', topic: 'Blood relations', difficulty: 'medium', q: 'A is the father of B. B is the sister of C. C is the son of D. How is D related to A?', right: 'Wife', wrong: ['Sister', 'Mother', 'Daughter-in-law'], explain: 'B is A\'s child and C is B\'s brother, so C is A\'s child too. D is C\'s parent. A is the father, so D is the other parent of A\'s children: A\'s wife.', seconds: 55, tags: ['blood-relations'] },
  { id: 'blood-photo', topic: 'Blood relations', difficulty: 'hard', q: 'Pointing to a man, a woman says, "His mother is the only daughter of my mother." How is the woman related to the man?', right: 'Mother', wrong: ['Sister', 'Aunt', 'Grandmother'], explain: 'The woman\'s mother has only one daughter, and that daughter is the man\'s mother. That daughter must be the woman herself, so she is his mother.', seconds: 60, tags: ['blood-relations'] },
  { id: 'blood-grandfather', topic: 'Blood relations', difficulty: 'easy', q: 'P is Q\'s brother. R is Q\'s mother. S is R\'s father. How is S related to P?', right: 'Grandfather', wrong: ['Father', 'Uncle', 'Great-grandfather'], explain: 'P and Q are siblings, so R is also P\'s mother. S is the father of P\'s mother, which makes him P\'s maternal grandfather.', seconds: 40, tags: ['blood-relations'] },
  { id: 'walk-back', topic: 'Directions', difficulty: 'easy', q: 'A man walks 10 m east, then 5 m south, then 10 m west. How far is he from his starting point?', right: '5 m', wrong: ['10 m', '15 m', '25 m'], explain: 'The 10 m east and 10 m west cancel each other, leaving only the 5 m he went south.', seconds: 30, tags: ['directions'] },
  { id: 'turn-anticlockwise', topic: 'Directions', difficulty: 'medium', q: 'A person faces south-east and turns 90° anticlockwise. Which direction does he now face?', right: 'North-east', wrong: ['South-west', 'North-west', 'South'], explain: 'Anticlockwise (to the left) from south-east goes through east to north-east. A clockwise turn would have given south-west.', seconds: 35, tags: ['directions'] },
  { id: 'row-seating', topic: 'Seating arrangement', difficulty: 'hard', q: 'Six people P, Q, R, S, T and U sit in a row facing north. T sits at the extreme left and U at the extreme right. R sits between P and S, with P to the left of S. Q sits immediately to the right of S. Who sits immediately to the left of U?', right: 'Q', wrong: ['S', 'R', 'P'], explain: 'T is first and U is last. The order inside must have P, R, S (R in the middle) followed directly by Q: T, P, R, S, Q, U. The person next to U on the left is Q.', seconds: 100, tags: ['seating', 'puzzle'] },
  { id: 'round-table', topic: 'Seating arrangement', difficulty: 'hard', q: 'Six friends A to F sit around a circular table facing the centre. Going clockwise, B is immediately after A. C sits opposite D. E sits opposite A. Going clockwise from F you reach D immediately. Who sits opposite B?', right: 'F', wrong: ['C', 'E', 'D'], explain: 'Starting with A at position 0 and B next at 1, E is opposite A at 3. C and D must take opposite seats among 2, 4 and 5, and D must follow F clockwise, giving A, B, C, E, F, D around the table. Position 4 (F) is opposite position 1 (B).', seconds: 110, tags: ['seating', 'circular'] },
  { id: 'syllogism-some', topic: 'Syllogisms', difficulty: 'medium', q: 'Statements: Some pens are pencils. All pencils are erasers.\nConclusions: I. Some pens are erasers.  II. All erasers are pencils.\nWhich conclusion follows?', right: 'Only I follows', wrong: ['Only II follows', 'Both I and II follow', 'Neither follows'], explain: 'The pens that are pencils are also erasers, so some pens are erasers (I). The reverse, that every eraser is a pencil, is not stated, so II does not follow.', seconds: 55, tags: ['syllogism'] },
  { id: 'syllogism-no', topic: 'Syllogisms', difficulty: 'hard', q: 'Statements: No cat is a dog. Some dogs are rats.\nConclusions: I. Some rats are not cats.  II. No rat is a cat.\nWhich conclusion follows?', right: 'Only I follows', wrong: ['Only II follows', 'Both I and II follow', 'Neither follows'], explain: 'The dogs that are rats can not be cats, so at least some rats are not cats (I). Other rats may be cats, so "no rat is a cat" is not certain.', seconds: 65, tags: ['syllogism'] },
  { id: 'assumption', topic: 'Logical reasoning', difficulty: 'medium', q: 'Statement: "Buy shoes from SpeedKart: they deliver within 2 days." Which is an implicit assumption?\nI. Many people value fast delivery.\nII. SpeedKart is the only shop that sells shoes.', right: 'Only I is implicit', wrong: ['Only II is implicit', 'Both are implicit', 'Neither is implicit'], explain: 'An advertiser mentions fast delivery because it expects customers to care about it (I). Nothing in the statement suggests that SpeedKart is the only seller (II).', seconds: 55, tags: ['assumption'] },
  { id: 'inequality-chain', topic: 'Inequalities', difficulty: 'medium', q: 'Given A ≥ B > C = D ≤ E, which conclusions follow?\nI. A > D  II. E > C', right: 'Only I follows', wrong: ['Only II follows', 'Both follow', 'Neither follows'], explain: 'A ≥ B and B > C = D give A > D (I). For II we only know D ≤ E and C = D, so E ≥ C; E could equal C, so "E > C" is not certain.', seconds: 55, tags: ['inequality'] },
  { id: 'inequality-link', topic: 'Inequalities', difficulty: 'medium', q: 'Given M < N ≤ O, O = P and P > Q, which conclusion is definitely true?', right: 'M < P', wrong: ['N < Q', 'Q < M', 'N > P'], explain: 'M < N ≤ O = P, so M < P. Nothing relates Q to M or N, so the other conclusions can not be drawn.', seconds: 45, tags: ['inequality'] },
  { id: 'odd-one-writing', topic: 'Odd one out', difficulty: 'easy', q: 'Find the odd one out: Pen, Pencil, Marker, Eraser.', right: 'Eraser', wrong: ['Marker', 'Pencil', 'Pen'], explain: 'Pens, pencils and markers are used to write or draw. An eraser removes marks instead.', seconds: 25, tags: ['odd-one-out'] },
  { id: 'analogy-work', topic: 'Analogies', difficulty: 'easy', q: 'Doctor : Hospital :: Teacher : ?', right: 'School', wrong: ['Student', 'Exam', 'Pupil'], explain: 'A doctor works in a hospital in the same way as a teacher works in a school: the relation is person to workplace.', seconds: 25, tags: ['analogy'] },
  { id: 'analogy-square', topic: 'Analogies', difficulty: 'easy', q: 'Find the missing number: 6 : 36 :: 7 : ?', right: '49', wrong: ['42', '56', '14'], explain: 'The second number is the square of the first: 6² = 36, so 7² = 49.', seconds: 25, tags: ['analogy', 'numbers'] },
  { id: 'calendar-march', topic: 'Calendars', difficulty: 'medium', q: 'If 5 March is a Monday, what day of the week is 25 March of the same year?', right: 'Sunday', wrong: ['Saturday', 'Monday', 'Friday'], explain: '25 March is 20 days after 5 March. 20 = 2 × 7 + 6, so the weekday moves 6 days forward: Monday → Sunday.', seconds: 40, tags: ['calendars'] },
  { id: 'row-between', topic: 'Ranking', difficulty: 'medium', q: 'In a row of 31 students, A is 10th from the left and B is 12th from the right. How many students are between A and B?', right: '9', wrong: ['8', '10', '11'], explain: 'B is 31 − 12 + 1 = 20th from the left. The students between positions 10 and 20 are 20 − 10 − 1 = 9.', seconds: 50, tags: ['ranking'] },
  { id: 'clock-overlap', topic: 'Clocks', difficulty: 'hard', q: 'How many times do the hour hand and the minute hand of a clock overlap in 12 hours?', right: '11', wrong: ['12', '10', '13'], explain: 'The hands overlap once every 12/11 hours, so there are 11 overlaps in a 12-hour cycle. The 12th would be the 12:00 at which the next cycle starts.', seconds: 55, tags: ['clocks'] },
]

const verbal: RawMcq[] = [
  { id: 'di-quarter-drop', topic: 'Data interpretation', difficulty: 'easy', q: 'Quarterly sales (in units) were: Q1 = 200, Q2 = 250, Q3 = 300, Q4 = 270. What was the percentage fall in sales from Q3 to Q4?', right: '10%', wrong: ['12%', '30%', '9%'], explain: 'The fall is 300 − 270 = 30 units on a base of 300, which is 10%. The base for a fall is the earlier value, Q3.', seconds: 40, tags: ['di', 'percentage'] },
  { id: 'di-budget', topic: 'Data interpretation', difficulty: 'medium', q: 'A company budget of ₹2,40,000 is split: salaries 40%, marketing 25%, rent 15%, other 20%. How much is spent on salaries and rent together?', right: '₹1,32,000', wrong: ['₹1,20,000', '₹1,44,000', '₹1,08,000'], explain: 'Salaries and rent make 40% + 15% = 55% of ₹2,40,000, which is ₹1,32,000.', seconds: 45, tags: ['di', 'pie-chart'] },
  { id: 'di-average-marks', topic: 'Data interpretation', difficulty: 'easy', q: 'A student scored Maths 80, Science 72, English 64 and Hindi 84. What is the average score?', right: '75', wrong: ['74', '76', '72'], explain: 'The total is 80 + 72 + 64 + 84 = 300 and 300 / 4 = 75.', seconds: 35, tags: ['di', 'average'] },
  { id: 'di-venn', topic: 'Data interpretation', difficulty: 'medium', q: 'Of 100 students, 60 like tea, 50 like coffee and 20 like both. How many like neither?', right: '10', wrong: ['20', '0', '30'], explain: 'Students who like at least one drink: 60 + 50 − 20 = 90. So 100 − 90 = 10 like neither.', seconds: 45, tags: ['di', 'sets'] },
  { id: 'di-production', topic: 'Data interpretation', difficulty: 'medium', q: 'A plant produced 4,500 units in January. February output was 20% higher than January, and March output was 10% lower than February. What was the March output?', right: '4,860 units', wrong: ['4,950 units', '4,800 units', '5,130 units'], explain: 'February = 4,500 × 1.2 = 5,400. March = 5,400 × 0.9 = 4,860. Adding +20% and −10% to the January figure gives 4,950, which is wrong.', seconds: 55, tags: ['di', 'percentage'] },
  { id: 'di-growth', topic: 'Data interpretation', difficulty: 'hard', q: 'Monthly revenue (in thousands): Jan 40, Feb 50, Mar 60, Apr 66. In which month was the percentage growth over the previous month the highest?', right: 'February', wrong: ['March', 'April', 'January'], explain: 'Growth: Feb 10/40 = 25%, Mar 10/50 = 20%, Apr 6/60 = 10%. February and March added the same amount, but February\'s smaller base gives the higher percentage. January has no earlier month.', seconds: 60, tags: ['di', 'growth'] },
  { id: 'synonym', topic: 'Vocabulary', difficulty: 'easy', q: 'Choose the word closest in meaning to METICULOUS.', right: 'Precise', wrong: ['Careless', 'Hasty', 'Boastful'], explain: '"Meticulous" means showing great attention to detail, so "precise" is the closest. "Careless" is the opposite.', seconds: 25, tags: ['vocabulary', 'synonym'] },
  { id: 'antonym', topic: 'Vocabulary', difficulty: 'easy', q: 'Choose the word opposite in meaning to SCARCE.', right: 'Abundant', wrong: ['Rare', 'Limited', 'Precious'], explain: '"Scarce" means in short supply; its opposite is "abundant", meaning plentiful. "Rare" and "limited" are near-synonyms.', seconds: 25, tags: ['vocabulary', 'antonym'] },
  { id: 'subject-verb', topic: 'Grammar', difficulty: 'medium', q: 'Fill in the blank: "The quality of these mangoes ___ poor."', right: 'is', wrong: ['are', 'were', 'have been'], explain: 'The subject is "the quality", which is singular; "of these mangoes" only modifies it. So the verb is "is".', seconds: 30, tags: ['grammar', 'agreement'] },
  { id: 'preposition', topic: 'Grammar', difficulty: 'easy', q: 'Fill in the blank: "She is very good ___ mathematics."', right: 'at', wrong: ['in', 'on', 'with'], explain: 'The adjective "good" takes the preposition "at" when it refers to a skill: good at mathematics.', seconds: 25, tags: ['grammar', 'prepositions'] },
  { id: 'one-word', topic: 'Vocabulary', difficulty: 'medium', q: 'Choose one word for "a person who can speak two languages fluently".', right: 'Bilingual', wrong: ['Polyglot', 'Linguist', 'Bilateral'], explain: '"Bilingual" means two languages. A polyglot knows many languages, a linguist studies language, and "bilateral" refers to two sides.', seconds: 30, tags: ['vocabulary', 'one-word'] },
  { id: 'idiom', topic: 'Idioms', difficulty: 'easy', q: 'What does the idiom "to break the ice" mean?', right: 'To ease tension and start a conversation', wrong: ['To end a friendship suddenly', 'To make a costly mistake', 'To cancel a meeting at the last moment'], explain: 'It describes doing or saying something to relax people who have just met, so that conversation can begin.', seconds: 25, tags: ['idioms'] },
  { id: 'di-two-products', topic: 'Data interpretation', difficulty: 'medium', q: 'Product A sold 120 units in 2019 and 150 in 2020. Product B sold 100 units in 2019 and 140 in 2020. Which grew faster in percentage terms?', right: 'B, with 40% growth against 25% for A', wrong: ['A, with 30 more units than 20', 'B, with 40 units against 30 units', 'Both grew by the same percentage'], explain: 'A grew by 30/120 = 25% and B by 40/100 = 40%. Comparing absolute growth is not the same as comparing growth rates.', seconds: 50, tags: ['di', 'growth'] },
  { id: 'di-savings', topic: 'Data interpretation', difficulty: 'easy', q: 'A family earns ₹80,000 a month and spends 30% on food, 25% on rent and 15% on transport. How much is left as savings?', right: '₹24,000', wrong: ['₹56,000', '₹20,000', '₹32,000'], explain: 'Spending is 30 + 25 + 15 = 70%, so savings are 30% of ₹80,000 = ₹24,000.', seconds: 40, tags: ['di', 'percentage'] },
  { id: 'di-temperature', topic: 'Data interpretation', difficulty: 'easy', q: 'The temperatures from Monday to Friday were 28, 30, 32, 34 and 36 degrees. What is the average temperature?', right: '32 degrees', wrong: ['31 degrees', '33 degrees', '34 degrees'], explain: 'The sum is 160, and 160 / 5 = 32. The values are evenly spaced, so the average equals the middle value.', seconds: 30, tags: ['di', 'average'] },
  { id: 'di-fail', topic: 'Data interpretation', difficulty: 'easy', q: 'In an exam taken by 200 students the pass percentage was 72%. How many students failed?', right: '56', wrong: ['44', '72', '28'], explain: 'The failing share is 100% − 72% = 28%, and 28% of 200 is 56. 144 passed.', seconds: 30, tags: ['di', 'percentage'] },
  { id: 'synonym-candid', topic: 'Vocabulary', difficulty: 'easy', q: 'Choose the word closest in meaning to CANDID.', right: 'Frank', wrong: ['Secretive', 'Polite', 'Shy'], explain: '"Candid" means open and honest in what you say, which is "frank".', seconds: 25, tags: ['vocabulary', 'synonym'] },
  { id: 'antonym-verbose', topic: 'Vocabulary', difficulty: 'medium', q: 'Choose the word opposite in meaning to VERBOSE.', right: 'Concise', wrong: ['Eloquent', 'Talkative', 'Fluent'], explain: '"Verbose" means using more words than needed; the opposite is "concise". "Talkative" is close to verbose, not opposite.', seconds: 25, tags: ['vocabulary', 'antonym'] },
  { id: 'conditional', topic: 'Grammar', difficulty: 'medium', q: 'Fill in the blank: "If I ___ you, I would apologise."', right: 'were', wrong: ['was', 'am', 'be'], explain: 'An unreal (hypothetical) condition uses the subjunctive "were" for every subject: "If I were you".', seconds: 25, tags: ['grammar', 'conditionals'] },
  { id: 'spelling', topic: 'Grammar', difficulty: 'easy', q: 'Which word is spelled correctly?', right: 'Accommodate', wrong: ['Acommodate', 'Accomodate', 'Acommodete'], explain: 'The word has a double "c" and a double "m": ac-com-mo-date.', seconds: 25, tags: ['spelling'] },
  { id: 'di-three-months', topic: 'Data interpretation', difficulty: 'easy', q: 'Sales (in ₹ lakh) were 40 in January, 50 in February and 60 in March. By what percentage did sales in March exceed those in January?', right: '50%', wrong: ['20%', '33⅓%', '25%'], explain: 'The increase is 60 − 40 = 20 on the January base of 40, which is 50%.', seconds: 35, tags: ['di', 'percentage'] },
  { id: 'di-pie-angle', topic: 'Data interpretation', difficulty: 'easy', q: 'In a pie chart, "Education" is 15% of a budget. What is the central angle of its slice?', right: '54°', wrong: ['45°', '60°', '15°'], explain: 'A full circle is 360°, and 15% of 360° is 54°.', seconds: 30, tags: ['di', 'pie-chart'] },
  { id: 'di-class-share', topic: 'Data interpretation', difficulty: 'medium', q: 'Four classes A, B, C and D have 30, 50, 70 and 50 students. What percentage of all the students are in class C?', right: '35%', wrong: ['30%', '25%', '40%'], explain: 'The total is 200, and 70 / 200 = 35%.', seconds: 35, tags: ['di', 'percentage'] },
  { id: 'di-managers', topic: 'Data interpretation', difficulty: 'medium', q: 'A company has 500 employees in the ratio 3 : 2 of men to women. If 40% of the women are managers, how many women are managers?', right: '80', wrong: ['120', '100', '200'], explain: 'Women are 2/5 of 500 = 200, and 40% of 200 is 80.', seconds: 50, tags: ['di', 'ratio'] },
  { id: 'di-margin', topic: 'Data interpretation', difficulty: 'easy', q: 'A firm had revenue of ₹500 and expenses of ₹420. What was its profit as a percentage of revenue?', right: '16%', wrong: ['19%', '84%', '8%'], explain: 'Profit = 500 − 420 = 80, and 80 / 500 = 16%. Dividing by the expenses would give 19%, which is a different measure.', seconds: 35, tags: ['di', 'profit'] },
  { id: 'di-line-fall', topic: 'Data interpretation', difficulty: 'medium', q: 'Production was 200 units in 2018, 230 in 2019 and 207 in 2020. By what percentage did production fall from 2019 to 2020?', right: '10%', wrong: ['3%', '11.5%', '15%'], explain: 'The fall is 230 − 207 = 23 units on the 2019 base of 230, which is 10%.', seconds: 40, tags: ['di', 'percentage'] },
  { id: 'di-weighted', topic: 'Data interpretation', difficulty: 'medium', q: 'Group A has 20 students with an average mark of 60, and group B has 30 students with an average of 70. What is the average mark of all 50 students?', right: '66', wrong: ['65', '67', '68'], explain: 'Use the weighted average: (20 × 60 + 30 × 70) / 50 = 3300 / 50 = 66. The simple average, 65, ignores that group B is larger.', seconds: 50, tags: ['di', 'average'] },
  { id: 'di-time-saved', topic: 'Data interpretation', difficulty: 'easy', q: 'A 240 km trip is made at an average of 60 km/h on one day and 80 km/h on another. How much time is saved on the faster day?', right: '1 hour', wrong: ['20 minutes', '30 minutes', '2 hours'], explain: 'The times are 240 / 60 = 4 hours and 240 / 80 = 3 hours, so 1 hour is saved.', seconds: 35, tags: ['di', 'speed'] },
  { id: 'di-rate-rise', topic: 'Data interpretation', difficulty: 'hard', q: 'A rate rose from 5% to 6%. By what percent did the rate itself rise?', right: '20%', wrong: ['1%', '6%', '10%'], explain: 'It rose by 1 percentage point, but relative to the old value of 5% the rise is 1 / 5 = 20%. Percentage points and percent are different.', seconds: 40, tags: ['di', 'percentage-points'] },
  { id: 'di-product-share', topic: 'Data interpretation', difficulty: 'easy', q: 'Products P, Q and R sold 120, 80 and 200 units in a month. What percentage of all units were product Q?', right: '20%', wrong: ['25%', '16%', '33%'], explain: 'The total is 400 units, and 80 / 400 = 20%.', seconds: 30, tags: ['di', 'percentage'] },
  { id: 'synonym-ephemeral', topic: 'Vocabulary', difficulty: 'medium', q: 'Choose the word closest in meaning to EPHEMERAL.', right: 'Short-lived', wrong: ['Eternal', 'Delicate', 'Ordinary'], explain: '"Ephemeral" describes something that lasts only a very short time, such as a mayfly or a trend.', seconds: 25, tags: ['vocabulary', 'synonym'] },
  { id: 'synonym-ubiquitous', topic: 'Vocabulary', difficulty: 'medium', q: 'Choose the word closest in meaning to UBIQUITOUS.', right: 'Everywhere', wrong: ['Hidden', 'Ancient', 'Unique'], explain: '"Ubiquitous" means seeming to be present everywhere at the same time, such as smartphones today.', seconds: 25, tags: ['vocabulary', 'synonym'] },
  { id: 'synonym-pragmatic', topic: 'Vocabulary', difficulty: 'medium', q: 'Choose the word closest in meaning to PRAGMATIC.', right: 'Practical', wrong: ['Idealistic', 'Dramatic', 'Cautious'], explain: 'A pragmatic person deals with things sensibly and realistically instead of following theories or ideals.', seconds: 25, tags: ['vocabulary', 'synonym'] },
  { id: 'antonym-benevolent', topic: 'Vocabulary', difficulty: 'medium', q: 'Choose the word opposite in meaning to BENEVOLENT.', right: 'Malevolent', wrong: ['Generous', 'Kindly', 'Humble'], explain: '"Benevolent" means well-meaning and kind; "malevolent" means wishing harm to others. "Generous" and "kindly" are synonyms.', seconds: 25, tags: ['vocabulary', 'antonym'] },
  { id: 'antonym-transparent', topic: 'Vocabulary', difficulty: 'easy', q: 'Choose the word opposite in meaning to TRANSPARENT.', right: 'Opaque', wrong: ['Clear', 'Thin', 'Glassy'], explain: 'A transparent material lets light pass through; an opaque one does not.', seconds: 20, tags: ['vocabulary', 'antonym'] },
  { id: 'antonym-diligent', topic: 'Vocabulary', difficulty: 'easy', q: 'Choose the word opposite in meaning to DILIGENT.', right: 'Lazy', wrong: ['Careful', 'Hardworking', 'Punctual'], explain: '"Diligent" means careful and hardworking; its opposite is "lazy".', seconds: 20, tags: ['vocabulary', 'antonym'] },
  { id: 'article-honest', topic: 'Grammar', difficulty: 'easy', q: 'Fill in the blank: "She is ___ honest woman."', right: 'an', wrong: ['a', 'the', 'no article'], explain: 'The article depends on the sound, not the spelling. "Honest" starts with a vowel sound (the "h" is silent), so we say "an honest woman".', seconds: 25, tags: ['grammar', 'articles'] },
  { id: 'tense-perfect', topic: 'Grammar', difficulty: 'medium', q: 'Fill in the blank: "By next June, I ___ in this company for ten years."', right: 'will have worked', wrong: ['worked', 'am working', 'had work'], explain: 'An action that will be complete at a future point is described with the future perfect: "will have worked".', seconds: 30, tags: ['grammar', 'tenses'] },
  { id: 'agreement-nor', topic: 'Grammar', difficulty: 'hard', q: 'Fill in the blank: "Neither Ravi nor his friends ___ present at the meeting."', right: 'were', wrong: ['was', 'is', 'has been'], explain: 'With "neither ... nor" the verb agrees with the noun closest to it. "His friends" is plural and the sentence is in the past, so the verb is "were".', seconds: 35, tags: ['grammar', 'agreement'] },
  { id: 'preposition-senior', topic: 'Grammar', difficulty: 'easy', q: 'Fill in the blank: "He is senior ___ me in the office."', right: 'to', wrong: ['than', 'from', 'over'], explain: 'Adjectives such as senior, junior, superior and inferior take "to", not "than".', seconds: 25, tags: ['grammar', 'prepositions'] },
  { id: 'doesnt', topic: 'Grammar', difficulty: 'easy', q: 'Fill in the blank: "He ___ like tea."', right: 'doesn\'t', wrong: ['don\'t', 'didn\'t likes', 'not'], explain: 'The subject "he" is third person singular, so the present-tense negative is "doesn\'t" followed by the base verb.', seconds: 20, tags: ['grammar', 'agreement'] },
  { id: 'reported-speech', topic: 'Grammar', difficulty: 'medium', q: 'Change to reported speech: He said, "I am tired."', right: 'He said that he was tired.', wrong: ['He said that I am tired.', 'He said that he is tired yesterday.', 'He told that he was tired.'], explain: 'In reported speech the pronoun changes from "I" to "he" and the present tense moves back to the past: "am" becomes "was".', seconds: 40, tags: ['grammar', 'reported-speech'] },
  { id: 'passive-voice', topic: 'Grammar', difficulty: 'medium', q: 'Choose the passive form of "The police caught the thief."', right: 'The thief was caught by the police.', wrong: ['The thief is caught by the police.', 'The police was caught by the thief.', 'The thief has caught the police.'], explain: 'The object becomes the subject and the verb takes "was" plus the past participle, keeping the simple past tense.', seconds: 35, tags: ['grammar', 'passive'] },
  { id: 'comparative-two', topic: 'Grammar', difficulty: 'easy', q: 'Fill in the blank: "Of the two books, this one is the ___."', right: 'better', wrong: ['best', 'good', 'more good'], explain: 'When two things are compared, the comparative form is used: "better". The superlative "best" is for three or more.', seconds: 25, tags: ['grammar', 'comparatives'] },
  { id: 'idiom-blue-moon', topic: 'Idioms', difficulty: 'easy', q: 'What does "once in a blue moon" mean?', right: 'Very rarely', wrong: ['Every month', 'At midnight', 'Without any warning'], explain: 'The phrase describes something that happens very seldom.', seconds: 20, tags: ['idioms'] },
  { id: 'idiom-cake', topic: 'Idioms', difficulty: 'easy', q: 'What does "a piece of cake" mean?', right: 'Something very easy', wrong: ['A small reward', 'A birthday present', 'Something sweet but unhealthy'], explain: 'Calling a task "a piece of cake" means it is very easy to do.', seconds: 20, tags: ['idioms'] },
  { id: 'idiom-beans', topic: 'Idioms', difficulty: 'easy', q: 'What does "to spill the beans" mean?', right: 'To reveal a secret', wrong: ['To make a mess', 'To cook a large meal', 'To lose money'], explain: 'To spill the beans is to let out a secret, usually by accident.', seconds: 20, tags: ['idioms'] },
  { id: 'idiom-nail', topic: 'Idioms', difficulty: 'medium', q: 'What does "to hit the nail on the head" mean?', right: 'To be exactly right', wrong: ['To work very hard', 'To hurt yourself while repairing', 'To start a quarrel'], explain: 'It means to describe or identify something with perfect accuracy.', seconds: 25, tags: ['idioms'] },
  { id: 'idiom-weather', topic: 'Idioms', difficulty: 'medium', q: 'What does "under the weather" mean?', right: 'Slightly unwell', wrong: ['Caught in the rain', 'Very cheerful', 'Living in a cold place'], explain: 'Feeling "under the weather" means feeling a little ill or low in energy.', seconds: 20, tags: ['idioms'] },
  { id: 'idiom-oil', topic: 'Idioms', difficulty: 'medium', q: 'What does "to burn the midnight oil" mean?', right: 'To work or study late into the night', wrong: ['To waste fuel', 'To start a fire by accident', 'To sleep very early'], explain: 'The phrase comes from the days of oil lamps and means working late at night.', seconds: 25, tags: ['idioms'] },
]

